import io.wayfarer.rpg.core.*;
import java.io.*;
import java.util.*;

/** Outcomes and counterplay for the harder encounters, two-stage skills, erosion and story decisions. */
public final class ChallengeTests {
    private static int checks;
    private static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    private static void near(float a,float b,String why){check(Math.abs(a-b)<.04f,why+": "+a+" vs "+b);}
    private static ActionGame arena(int weapon,int soul){ActionGame g=new ActionGame();g.selectHero(weapon);g.bindSoul(soul,0);g.start(91);g.blocks.clear();g.enemies.clear();g.hazards.clear();g.x=560;g.y=600;g.invulnerable=0;return g;}
    private static ActionGame.Enemy mob(ActionGame g,int type,float x,float y){ActionGame.Enemy e=new ActionGame.Enemy(g.nextId++,type,x,y,1000);g.enemies.add(e);return e;}
    private static void step(ActionGame g,int frames,boolean freeze){for(int i=0;i<frames;i++){if(freeze)for(ActionGame.Enemy e:g.enemies)e.stun=1;g.hitStop=0;g.update(1f/60,new ActionGame.Input());g.signals.clear();}}
    private static byte[] edit(byte[] data,String key,String val)throws Exception{Properties p=new Properties();p.load(new ByteArrayInputStream(data));p.setProperty(key,val);ByteArrayOutputStream o=new ByteArrayOutputStream();p.store(o,"");return o.toByteArray();}
    private static void reject(byte[] bytes,String key,String val)throws Exception{boolean bad=false;try{ActionSave.decode(edit(bytes,key,val));}catch(IOException e){bad=true;}check(bad,"reject "+key);}
    private static void skills()throws Exception{
        ActionGame g=new ActionGame();g.chooseCareer(CareerSystem.HUNTER,0,0);g.start(1);g.blocks.clear();g.enemies.clear();g.x=560;g.y=600;g.hp=50;ActionGame.Enemy e=mob(g,0,700,600);float baseSpeed=g.speed();g.skill();check(g.careerSkillMode==1&&g.careerSkillTime==30&&e.hp<1000&&g.speed()>baseSpeed,"hunter opens with a wide burst and enters a thirty-second speed state");g.hp=50;float postBurstHp=g.hp;step(g,65,true);check(g.hp<postBurstHp&&g.hp>=g.maxHp()*.30f-.01f,"hunter pays life over time but never drains below thirty percent");
        g=new ActionGame();g.chooseCareer(CareerSystem.ASSASSIN,0,0);g.start(2);g.blocks.clear();g.enemies.clear();g.x=560;g.y=600;g.invulnerable=0;ActionGame.Enemy target=mob(g,0,690,600);target.hp=1;target.maxHp=1;float period=g.attackPeriod(),startHp=g.maxHp()-10;g.hp=startHp;g.skill();check(g.careerSkillMode==2&&g.careerSkillTime==30&&g.attackPeriod()>period,"assassin enters knife fan state with a slight attack-speed penalty");ActionGame.Input attack=new ActionGame.Input();attack.attack=true;g.update(.001f,attack);check(g.shots.size()==3,"assassin attack emits exactly three fan knives");g.activeSkillCd=8;for(int i=0;i<8;i++){g.hitStop=0;g.update(.05f,attack);}check(g.activeSkillCd==0&&g.skillCd>0&&g.hp>startHp,"assassin kill resets generic active skill, preserves career skill cooldown, and restores three-percent maximum health");
        g=new ActionGame();g.selectHero(2);g.start(1);g.blocks.clear();g.enemies.clear();g.invulnerable=0;ActionGame.Input dagger=new ActionGame.Input();dagger.attack=true;g.update(.001f,dagger);check(g.attackAnim>.17f&&g.invulnerable==0&&g.attackPeriod()>=.12f,"dagger thrust has no granted invulnerability and a longer attack interval");
        g=new ActionGame();g.chooseCareer(CareerSystem.DETECTIVE,0,0);g.start(3);g.blocks.clear();g.enemies.clear();g.x=560;g.y=600;e=mob(g,0,720,600);float detectiveDistance=(float)Math.hypot(e.x-g.x,e.y-g.y);g.skill();check(g.careerSkillMode==0&&g.careerSkillTime==0&&e.x<720&&e.hp<1000&&Math.hypot(e.x-g.x,e.y-g.y)<detectiveDistance,"detective performs a one-shot global pull, damage and brief stun");
        g=new ActionGame();g.chooseCareer(CareerSystem.REPORTER,0,0);g.start(4);g.blocks.clear();g.enemies.clear();e=mob(g,0,700,600);float expected=g.damage()*1.3f;g.skill();near(1000-e.hp,expected,"reporter single-target skill delivers focused burst");check(g.careerSkillMode==0&&g.careerSkillTime==0,"reporter burst does not retain obsolete attack/healing state");
        g.soulCd=8;g.generateRoom();check(g.skillCd==0&&g.soulCd==0,"new scene resets all skill cooldowns");
        ActionGame restored=ActionSave.decode(ActionSave.encode(g));check(restored.job()==CareerSystem.REPORTER&&restored.careerCooldownRank==g.careerCooldownRank,"career cooldown progression persists");
        System.out.println("PASS four redesigned career skills, costs, cooldowns and scene resets");
    }
    private static void erosion()throws Exception{
        ActionGame g=arena(0,2);mob(g,0,100,100);g.corruption=80;g.soulSkill();
        check(g.corruption>=100&&g.ruptureTime>0&&g.ruptureLatched&&g.soulBuff>0,"soul skill crossing 100 immediately triggers five-second overrun");
        float hp=g.hp,rt=g.ruptureTime;g.pause();step(g,60,true);near(g.ruptureTime,rt,"paused overrun timer freezes");
        ActionGame a=ActionSave.decode(ActionSave.encode(g));a.resume();g.resume();step(g,100,true);step(a,100,true);check(g.hp<hp,"overrun causes periodic life loss");near(a.hp,g.hp,"restore preserves rupture pulse");near(a.ruptureTime,g.ruptureTime,"restore preserves remaining overrun");
        g=arena(0,2);mob(g,0,100,100);g.corruption=40;step(g,60,true);check(g.corruption<40&&g.corruption>39,"erosion decays immediately");
        System.out.println("PASS erosion decay, threshold trigger, overrun timer and save continuity");
    }
    private static void enemies()throws Exception{
        ActionGame g=arena(0,0);ActionGame.Enemy rifle=mob(g,1,700,600);rifle.state=1;rifle.timer=.001f;rifle.aimX=-1;rifle.aimY=0;step(g,1,false);check(g.shots.size()==3,"rifle first volley has three lines of fire");g.shots.clear();rifle.timer=.51f;step(g,2,false);check(rifle.struck&&g.shots.size()==3,"rifle releases second staggered volley");
        g=arena(0,0);ActionGame.Enemy leaper=mob(g,4,760,600);ActionGame.Input move=new ActionGame.Input();move.my=-1;g.update(.05f,move);check(leaper.state==1&&leaper.targetY<600,"hunter predicts moving target before committing");float aim=leaper.aimY;g.x=300;g.update(.05f,new ActionGame.Input());near(leaper.aimY,aim,"leap aim stays locked and remains dodgeable");
        g=arena(0,0);ActionGame.Enemy burner=mob(g,5,800,600);burner.state=1;burner.timer=.001f;burner.targetX=g.x;burner.targetY=g.y;burner.aimX=-1;burner.aimY=0;step(g,1,false);check(g.hazards.size()==2,"burner lays two distinct delayed denial zones");float hp=g.hp;step(g,30,true);near(g.hp,hp,"warning period does not damage");g.pause();ActionGame saved=ActionSave.decode(ActionSave.encode(g));near(saved.hazards.get(0).warning,g.hazards.get(0).warning,"warning survives pause and save");g.resume();saved.resume();step(g,50,true);step(saved,50,true);check(g.hp<hp,"standing in armed zone really hurts");near(g.hp,saved.hp,"resumed zone maintains the same first damage time");
        g=arena(0,0);mob(g,0,100,100);g.hazards.add(new ActionGame.Hazard(0,g.x,g.y,82,1,2,15));move.mx=-1;move.my=0;for(int i=0;i<65;i++){g.enemies.get(0).stun=1;g.update(1f/60,move);}near(g.hp,g.maxHp(),"walking out of telegraphed zone avoids damage");
        g=arena(0,0);ActionGame.Enemy bell=mob(g,6,800,600),ally=mob(g,0,700,600);bell.state=1;bell.timer=.001f;ally.stun=1;step(g,1,false);check(ally.guard==24&&bell.guard==0,"bell bearer supports an ally, not itself");g.shots.clear();float health=ally.hp;g.shots.add(new ActionGame.Shot(ally.x,ally.y,0,0,20,true));step(g,1,true);near(ally.hp,health,"guard absorbs real player hit");near(ally.guard,4,"absorbed damage consumes guard");
        g=arena(0,0);ActionGame.Enemy boss=mob(g,3,700,400);for(int p=0;p<3;p++){g.hazards.clear();g.shots.clear();boss.pattern=p;boss.state=1;boss.timer=.001f;boss.stun=0;boss.targetX=g.x;boss.targetY=g.y;boss.aimX=0;boss.aimY=1;step(g,1,false);if(p==0)check(!g.hazards.isEmpty()&&g.shots.size()==12,"boss first pattern combines expanding pressure with radial shots");if(p==1)check(g.shots.size()==5&&g.hazards.isEmpty(),"boss second pattern is aimed barrage");if(p==2)check(g.hazards.size()==3&&g.shots.isEmpty(),"boss third pattern closes three staggered ground positions");}
        boss.state=0;boss.hp=400;boss.stun=0;step(g,1,false);near(boss.timer,.72f,"half-health phase shortens telegraph but does not eliminate it");boss.state=3;boss.timer=1;boss.hp=500;boss.guard=0;step(g,30,false);check(boss.hp>500&&boss.guard>0,"boss restores health and rebuilds guard during recovery, faster while enraged");boss.guard=89;ActionGame bossSave=ActionSave.decode(ActionSave.encode(g));near(bossSave.enemies.get(0).guard,89,"version 21 saves and restores boss guard above the ordinary-enemy cap");
        for(int room=1;room<=5;room++){g=new ActionGame();g.start(1);g.room=room;g.generateRoom();check(g.enemies.size()==EncounterSystem.GROUPS[room-1].length,"encounter roster is populated");int bosses=0;for(ActionGame.Enemy e:g.enemies){check(g.free(e.x,e.y,e.radius()),"all new archetypes spawn in valid space");if(e.type==3)bosses++;}check(bosses==(room==2||room==4||room==5?1:0),"boss placement matches encounter tier");ActionSave.decode(ActionSave.encode(g));}check(!EncounterSystem.bossName(2).equals(EncounterSystem.bossName(4))&&!EncounterSystem.bossName(4).equals(EncounterSystem.bossName(5)),"each boss arena has a distinct identity");
        System.out.println("PASS volleys, predictive locked leaps, delayed hazards, support shields, three boss arenas and escalating boss patterns");
    }
    private static void clear(ActionGame g,int room){g.room=room;g.generateRoom();for(ActionGame.Enemy e:g.enemies)e.hp=0;g.update(.05f,new ActionGame.Input());g.signals.clear();}
    private static void story()throws Exception{
        ActionGame g=new ActionGame();g.chooseCareer(CareerSystem.HUNTER,0,0);g.start(1);check(!g.decideStory(0,1),"undiscovered story cannot be chosen in combat");clear(g,1);check(g.storyUnlocked==1&&g.characterUnlocked[0]==1&&g.characterJobs[0]==CareerSystem.HUNTER,"actual room clear unlocks main and current character hook");int bank=g.bank;check(g.decideStory(0,1)&&g.bank==bank+12,"story rescue choice gives one actual permanent reward");check(!g.decideStory(0,2)&&g.bank==bank+12,"cannot change decision or claim alternate reward");g.chooseReward(0);clear(g,3);int xp=g.heroXp();check(g.decideStory(2,2)&&g.heroXp()==xp+20,"evidence choice grants experience to selected role");clear(g,5);check(g.won&&g.characterUnlocked[0]==7,"boss clear unlocks character conclusion");g.returnCamp();float max=g.maxHp();check(g.decideCharacter(0,1)&&g.maxHp()==max+4,"personal protective decision creates persistent passive");float power=g.damage();check(g.decideCharacter(1,2)&&g.damage()==power+1,"personal decisive choice creates persistent attack passive");check(!g.decideCharacter(1,1),"character passive cannot be farmed");g.chooseCareer(CareerSystem.REPORTER,0,0);check(g.characterJobs[0]==CareerSystem.HUNTER,"changing profession cannot rewrite recorded character story");
        ActionGame a=ActionSave.decode(ActionSave.encode(g));check(a.storyChoices[0]==1&&a.storyChoices[2]==2&&a.characterChoices[0][1]==2&&a.characterJobs[0]==CareerSystem.HUNTER,"main and character choices survive snapshot");near(a.maxHp(),g.maxHp(),"story health passive restores before HP validation");a.selectHero(1);check(a.characterJobs[1]==-1&&a.characterTrait(1)==0&&a.characterTrait(2)==0,"another character has an independent story and passives");
        check(StorySystem.ending(new int[]{1,1,1,1,1}).contains("归途有名"),"rescue ending");check(StorySystem.ending(new int[]{2,2,2,2,2}).contains("墨迹未干"),"evidence ending");check(StorySystem.ending(new int[]{1,1,1,2,2}).contains("灯下余声"),"mixed ending");
        System.out.println("PASS actual scene unlocks, two main choice rewards, independent three-beat character arcs, immutable records and endings");
    }
    private static void snapshots()throws Exception{
        ActionGame g=arena(0,0);mob(g,0,700,600);g.skill();byte[] b=ActionSave.encode(g);
        reject(b,"followUpWindow","3");reject(b,"hazards","19");reject(b,"storyChoice0","1");reject(b,"characterUnlocked0","2");reject(b,"characterChoice0.0","1");reject(b,"ruptureTime","1");
        g=new ActionGame();g.experience[0]=160;g.chooseCareer(CareerSystem.REPORTER,2,4);g.bindSoul(2,1);g.start(1);g.soulSkill();
        ActionGame a=ActionSave.decode(ActionSave.encode(g));check(a.job()==CareerSystem.REPORTER&&a.specialization()==2&&a.background()==4&&a.soulBuff==g.soulBuff,"new career schema roundtrips with soul and background");
        System.out.println("PASS four-career snapshot provenance and bounded state rejection");
    }
    private static void specialties()throws Exception{
        ActionGame g=new ActionGame();g.experience[0]=320;g.bindSoul(1,0);
        check(g.learnSpecialty(0)&&g.learnSpecialty(0)&&g.learnSpecialty(1)&&g.learnSpecialty(1)&&g.learnSpecialty(3),"pact path follows prerequisites and permits one capstone");
        check(g.availableSpecialtyPoints()==1&&g.availablePoints()==6&&g.learn(0)&&g.availablePoints()==5&&g.availableSpecialtyPoints()==1,"base talents and specialties use independent point budgets");
        float expected=40+16;g.start(31);near(g.soulEnergy,expected,"pact path increases expedition starting soul energy");near(g.soulPeriod(),SoulSystem.COOLDOWNS[1][0]-1.6f,"deep current shortens soul cooldown");
        ActionGame restored=ActionSave.decode(ActionSave.encode(g));check(restored.specialties[0][0]==2&&restored.specialties[0][3]==1,"specialty ranks persist in v22 snapshots");
        g=new ActionGame();g.experience[0]=320;g.learnSpecialty(4);g.learnSpecialty(4);g.learnSpecialty(5);g.learnSpecialty(6);
        check(g.specialtyRank(6)==1&&!g.learnSpecialty(7),"hunting capstones are mutually exclusive");
        float ordinary=g.damage();ActionGame baseline=new ActionGame();baseline.start(1);ActionGame.Enemy baseMarked=new ActionGame.Enemy(1,0,700,600,1000);baseline.enemies.add(baseMarked);baseMarked.hex=3;baseline.hitForTest(baseMarked,100);ActionGame.Enemy e=new ActionGame.Enemy(2,0,700,600,1000);g.enemies.add(e);e.hex=3;g.hitForTest(e,100);
        near((baseMarked.maxHp-baseMarked.hp)*1.10f,e.maxHp-e.hp,"marked target takes ten percent more damage than the same cursed target without the specialization");
        check(g.damage()>baseline.damage(),"hunting instinct changes baseline combat damage");
        ActionGame other=new ActionGame();other.selectHero(1);check(other.specialtyRank(4)==0,"specialty progress is independent per character");
        System.out.println("PASS pact and hunting specialization prerequisites, shared points, combat effects, character isolation and save migration");
    }
    private static void pressure(){
        int hurtRuns=0;float damage=0;
        for(int seed=1;seed<=12;seed++){ActionGame g=new ActionGame();g.start(seed);g.room=3;g.generateRoom();g.x=560;g.y=420;float hp=g.hp;ActionGame.Input in=new ActionGame.Input();for(int t=0;t<1200&&g.mode==ActionGame.Mode.PLAY;t++){in.mx=(float)Math.cos(t*.025);in.my=(float)Math.sin(t*.025);g.update(1f/60,in);g.signals.clear();}if(g.hp<hp)hurtRuns++;damage+=hp-g.hp;}
        check(hurtRuns>=9,"simple circular running should not trivialize mixed encounters: "+hurtRuns+"/12");System.out.println("PASS pressure benchmark: basic circular movement hurt in "+hurtRuns+"/12 seeded encounters; mean loss "+String.format(Locale.ROOT,"%.1f",damage/12)+" HP (not a claim about optimal human play)");
    }
    public static void main(String[] args)throws Exception{skills();erosion();enemies();story();snapshots();specialties();pressure();System.out.println("CHALLENGE CHECKS PASSED: "+checks);}
}
